import { describe, expect, test } from "bun:test";
import crypto from "node:crypto";
import { EventEmitter } from "node:events";
import path from "node:path";
import { b64url, encrypt, isAllowedEndpoint, sendPush, validSubscriptionKeys, validVapid, vapidAuthorization } from "../lib/webpush.js";
import { sleep } from "./support";

// Nothing in here touches the network or sends a push: sendPush gets a stub `request`, and every key
// is generated by the test. The only fixed values are the RFC 8291 example's.

const b = (text: string) => Buffer.from(text, "base64url");
const APPLE = "https://web.push.apple.com/QAbc";
const SUBJECT = "https://app.example.test";
const FAILED = { ok: false, status: 0, gone: false };

// --- keys the way a browser makes them ------------------------------------------------------

interface Subscriber {
  privateKey: Buffer;
  publicKey: Buffer;
  auth: Buffer;
  keys: { p256dh: string; auth: string };
}

/** A push subscription's keys: a P-256 key pair (the public half as the 65-byte point) and a 16-byte auth secret. */
function makeSubscriber(): Subscriber {
  const ecdh = crypto.createECDH("prime256v1");
  ecdh.generateKeys();
  const auth = crypto.randomBytes(16);
  const publicKey = ecdh.getPublicKey();
  return {
    privateKey: ecdh.getPrivateKey(),
    publicKey,
    auth,
    keys: { p256dh: publicKey.toString("base64url"), auth: auth.toString("base64url") },
  };
}

interface Jwk {
  kty: string;
  crv: string;
  x: string;
  y: string;
  d: string;
  [member: string]: unknown;
}

/** VAPID keys as the app makes them: the raw public key, base64url, and the private key as a JWK. */
function makeVapid() {
  const { privateKey } = crypto.generateKeyPairSync("ec", { namedCurve: "prime256v1" });
  const privateJwk = privateKey.export({ format: "jwk" }) as unknown as Jwk;
  const publicKey = Buffer.concat([Buffer.from([4]), b(privateJwk.x), b(privateJwk.y)]).toString("base64url");
  return { publicKey, privateJwk };
}

/** A string of `length` random bytes, the first one set, as base64url. */
const bytes = (length: number, first = 4) => Buffer.concat([Buffer.from([first]), crypto.randomBytes(length - 1)]).toString("base64url");

/** The same bytes in the standard base64 alphabet (+ and / for - and _), without padding. */
const standardBase64 = (text: string) => b(text).toString("base64").replace(/=+$/, "");

// --- what a push service and a browser do with a message ------------------------------------

/** The browser's side of RFC 8291 section 3.4: opens a body with the subscriber's private key and returns the payload. */
function decrypt(body: Buffer, subscriber: Subscriber): Buffer {
  const salt = body.subarray(0, 16);
  const idLength = body[20];
  const senderPublic = body.subarray(21, 21 + idLength);
  const sealed = body.subarray(21 + idLength);
  const ecdh = crypto.createECDH("prime256v1");
  ecdh.setPrivateKey(subscriber.privateKey);
  const secret = ecdh.computeSecret(senderPublic);
  const info = Buffer.concat([Buffer.from("WebPush: info\0"), subscriber.publicKey, senderPublic]);
  const ikm = Buffer.from(crypto.hkdfSync("sha256", secret, subscriber.auth, info, 32));
  const cek = Buffer.from(crypto.hkdfSync("sha256", ikm, salt, Buffer.from("Content-Encoding: aes128gcm\0"), 16));
  const nonce = Buffer.from(crypto.hkdfSync("sha256", ikm, salt, Buffer.from("Content-Encoding: nonce\0"), 12));
  const decipher = crypto.createDecipheriv("aes-128-gcm", cek, nonce);
  decipher.setAuthTag(sealed.subarray(sealed.length - 16));
  const record = Buffer.concat([decipher.update(sealed.subarray(0, sealed.length - 16)), decipher.final()]);
  expect(record[record.length - 1]).toBe(0x02); // the last record's delimiter, and no padding after it
  return record.subarray(0, record.length - 1);
}

/** Takes a `vapid t=<jwt>, k=<key>` header apart. */
function parseVapid(header: string) {
  const match = /^vapid t=([\w-]+)\.([\w-]+)\.([\w-]+), k=([\w-]+)$/.exec(header);
  if (!match) throw new Error(`not a VAPID header: ${header}`);
  const [, head, claims, signature, key] = match;
  return {
    signingInput: `${head}.${claims}`,
    header: Buffer.from(head, "base64url").toString(),
    claims: JSON.parse(Buffer.from(claims, "base64url").toString()),
    signature: Buffer.from(signature, "base64url"),
    key,
  };
}

/** What the push service does: checks the JWT's signature with the raw public key from `k`. */
function verifies(parsed: ReturnType<typeof parseVapid>): boolean {
  const raw = b(parsed.key);
  const publicKey = crypto.createPublicKey({
    key: { kty: "EC", crv: "P-256", x: raw.subarray(1, 33).toString("base64url"), y: raw.subarray(33).toString("base64url") },
    format: "jwk",
  });
  return crypto.verify("sha256", Buffer.from(parsed.signingInput), { key: publicKey, dsaEncoding: "ieee-p1363" }, parsed.signature);
}

// --- a stand-in for https.request -----------------------------------------------------------

interface Call {
  url: string;
  method: string;
  headers: Record<string, string>;
  body: Buffer;
  /** The request's end() was called: the body is complete. */
  ended: boolean;
  destroyed: boolean;
  /** The response was resumed, which is how a response body is drained. */
  drained: boolean;
}

type Answer = (status: number) => EventEmitter;
type Script = (req: EventEmitter, answer: Answer) => void;

/**
 * A `request` that records every call and plays the push service through `script`, which runs when the
 * request is ended: it can answer with a status, emit an error on the request, or do nothing at all.
 */
function fakeRequest(script: Script = (_req, answer) => answer(201)) {
  const calls: Call[] = [];
  const request = (url: unknown, options: any, onResponse: (res: any) => void) => {
    const call: Call = { url: String(url), method: options.method, headers: options.headers, body: Buffer.alloc(0), ended: false, destroyed: false, drained: false };
    calls.push(call);
    const req: any = new EventEmitter();
    req.write = (chunk: Buffer | string) => {
      call.body = Buffer.concat([call.body, Buffer.from(chunk)]);
      return true;
    };
    req.end = (chunk?: Buffer | string) => {
      if (chunk !== undefined) req.write(chunk);
      call.ended = true;
      script(req, (status) => {
        const res: any = new EventEmitter();
        res.statusCode = status;
        res.resume = () => {
          call.drained = true;
          // A real response ends once its body has been read. The timer is cleared on 'end' or 'close',
          // not when the status settles, so a stub that never ends would keep it armed.
          queueMicrotask(() => res.emit("end"));
        };
        onResponse(res);
        return res;
      });
    };
    req.destroy = () => {
      call.destroyed = true;
    };
    return req;
  };
  return { request, calls };
}

/** A push to the Apple endpoint with fresh keys; `overrides` change fields of the push. */
function makePush(overrides: Record<string, unknown> = {}) {
  const subscriber = makeSubscriber();
  const vapid = makeVapid();
  const push = {
    endpoint: APPLE,
    keys: subscriber.keys,
    vapid,
    subject: SUBJECT,
    payload: JSON.stringify({ v: 1, kind: "waiting", title: "Project", body: "Allow Bash: ls?" }),
    ttl: 3600,
    urgency: "high",
    topic: "k3X-0_abcDEF123",
    ...overrides,
  };
  return { push, subscriber, vapid };
}

// --- encrypt --------------------------------------------------------------------------------

describe("encrypt", () => {
  test("encrypts the RFC 8291 §5 example byte for byte", () => {
    const body = encrypt(
      b("V2hlbiBJIGdyb3cgdXAsIEkgd2FudCB0byBiZSBhIHdhdGVybWVsb24"),
      { p256dh: "BCVxsr7N_eNgVRqvHtD0zTZsEc6-VV-JvLexhqUzORcxaOzi6-AYWXvTBHm4bjyPjs7Vd8pZGH6SRpkNtoIAiw4", auth: "BTBZMqHH6r4Tts7J_aSIgg" },
      { salt: b("DGv6ra1nlYgDCS1FRnbzlw"), serverPrivateKey: b("yfWPiYE-n46HLnH0KqZOF1fJJU3MYrct3AELtAQ-oRw") },
    );
    expect(body.toString("base64url")).toBe(
      "DGv6ra1nlYgDCS1FRnbzlwAAEABBBP4z9KsN6nGRTbVYI_c7VJSPQTBtkgcy27mlmlMoZIIgDll6e3vCYLocInmYWAmS6TlzAC8wEqKK6PBru3jl7A_yl95bQpu6cVPTpK4Mqgkf1CXztLVBSt2Ks3oZwbuwXPXLWyouBWLVWGNWQexSgSxsj_Qulcy4a-fN",
    );
  });

  test("round-trips with a subscriber's keys", () => {
    const subscriber = makeSubscriber();
    const payload = '{"hello":"wörld 🎉"}';
    const body = encrypt(payload, subscriber.keys);
    expect(decrypt(body, subscriber).toString("utf8")).toBe(payload);
  });

  test("takes a Buffer payload as well as a string", () => {
    const subscriber = makeSubscriber();
    const payload = crypto.randomBytes(300);
    expect(decrypt(encrypt(payload, subscriber.keys), subscriber).equals(payload)).toBe(true);
  });

  test("lays the body out as header, sender key and one sealed record", () => {
    const subscriber = makeSubscriber();
    const payload = Buffer.from("hello");
    const body = encrypt(payload, subscriber.keys);
    expect(body.readUInt32BE(16)).toBe(4096); // rs
    expect(body[20]).toBe(65); // idlen
    expect(body[21]).toBe(0x04); // the sender's key is an uncompressed point
    expect(body).toHaveLength(16 + 4 + 1 + 65 + payload.length + 1 + 16); // the delimiter and the GCM tag, no padding
  });

  test("uses a fresh salt and sender key for every message", () => {
    const subscriber = makeSubscriber();
    const first = encrypt("same", subscriber.keys);
    const second = encrypt("same", subscriber.keys);
    expect(first.subarray(0, 16).equals(second.subarray(0, 16))).toBe(false);
    expect(first.subarray(21, 86).equals(second.subarray(21, 86))).toBe(false);
  });

  test("throws a TypeError for keys of the wrong length or shape", () => {
    const { keys } = makeSubscriber();
    const bad: unknown[] = [
      { ...keys, p256dh: bytes(64) },
      { ...keys, p256dh: bytes(66) },
      { ...keys, p256dh: bytes(65, 3) },
      { ...keys, auth: bytes(15) },
      { ...keys, auth: bytes(17) },
      { ...keys, p256dh: `${keys.p256dh}=` },
      { ...keys, p256dh: 42 },
      { p256dh: keys.p256dh },
      {},
      null,
      undefined,
    ];
    for (const wrong of bad) expect(() => encrypt("x", wrong as any)).toThrow(TypeError);
  });

  test("throws a TypeError for a payload that is neither text nor bytes, and for a salt that is not 16 bytes", () => {
    const { keys } = makeSubscriber();
    expect(() => encrypt(42 as any, keys)).toThrow(TypeError);
    expect(() => encrypt(undefined as any, keys)).toThrow(TypeError);
    expect(() => encrypt([1, 2, 3] as any, keys)).toThrow(TypeError); // Buffer.from would take an array of numbers
    expect(() => encrypt("x", keys, { salt: crypto.randomBytes(15) })).toThrow(TypeError);
  });

  test("throws a RangeError for a payload that does not fit the one record, instead of building an invalid body", () => {
    const subscriber = makeSubscriber();
    expect(() => encrypt(Buffer.alloc(4080), subscriber.keys)).toThrow(RangeError);
    // 4079 bytes plus the delimiter and the tag fill the record exactly
    const largest = crypto.randomBytes(4079);
    expect(decrypt(encrypt(largest, subscriber.keys), subscriber).equals(largest)).toBe(true);
  });
});

// --- vapidAuthorization ---------------------------------------------------------------------

describe("vapidAuthorization", () => {
  test("signs a VAPID JWT the public key verifies", () => {
    const vapid = makeVapid();
    const now = 1_800_000_000_123;
    const header = vapidAuthorization({ endpoint: APPLE, publicKey: vapid.publicKey, privateJwk: vapid.privateJwk, subject: SUBJECT, now });
    expect(header).toStartWith("vapid t=");
    const parsed = parseVapid(header);
    expect(parsed.key).toBe(vapid.publicKey);
    expect(parsed.header).toBe('{"typ":"JWT","alg":"ES256"}');
    expect(parsed.claims).toEqual({ aud: "https://web.push.apple.com", exp: Math.floor(now / 1000) + 43200, sub: SUBJECT });
    expect(parsed.signature).toHaveLength(64); // raw r || s, not DER
    expect(verifies(parsed)).toBe(true);
    // the check above is not vacuous: it fails for another signing input and for another key
    expect(verifies({ ...parsed, signingInput: `${parsed.signingInput}x` })).toBe(false);
    expect(verifies({ ...parsed, key: makeVapid().publicKey })).toBe(false);
  });

  test("the audience is the endpoint's origin: scheme, host and port, no path or query", () => {
    const vapid = makeVapid();
    const audienceOf = (endpoint: string) => parseVapid(vapidAuthorization({ endpoint, publicKey: vapid.publicKey, privateJwk: vapid.privateJwk, subject: SUBJECT })).claims.aud;
    expect(audienceOf("https://updates.push.services.mozilla.com/wpush/v2/abc?x=1")).toBe("https://updates.push.services.mozilla.com");
    expect(audienceOf("https://fcm.googleapis.com:443/fcm/send/abc")).toBe("https://fcm.googleapis.com");
    expect(audienceOf("http://127.0.0.1:8123/push/abc")).toBe("http://127.0.0.1:8123");
  });

  test("expires 12 hours after now by default; now and the lifetime can be set", () => {
    const vapid = makeVapid();
    const sign = (extra: Record<string, unknown> = {}) =>
      parseVapid(vapidAuthorization({ endpoint: APPLE, publicKey: vapid.publicKey, privateJwk: vapid.privateJwk, subject: SUBJECT, ...extra })).claims.exp;
    const before = Math.floor(Date.now() / 1000);
    const exp = sign();
    const after = Math.floor(Date.now() / 1000);
    expect(exp).toBeGreaterThanOrEqual(before + 43200);
    expect(exp).toBeLessThanOrEqual(after + 43200);
    expect(sign({ now: 5_000_999, expSeconds: 600 })).toBe(5000 + 600);
  });

  test("throws for a key it cannot sign with", () => {
    const vapid = makeVapid();
    expect(() => vapidAuthorization({ endpoint: APPLE, publicKey: vapid.publicKey, privateJwk: { kty: "EC" } as any, subject: SUBJECT })).toThrow();
    expect(() => vapidAuthorization({ endpoint: "not a url", publicKey: vapid.publicKey, privateJwk: vapid.privateJwk, subject: SUBJECT })).toThrow();
  });
});

// --- the endpoint allowlist -----------------------------------------------------------------

describe("isAllowedEndpoint", () => {
  test("allows only known push services over https", () => {
    for (const url of [
      "https://web.push.apple.com/x",
      "https://api.push.apple.com/x",
      "https://fcm.googleapis.com/fcm/send/x",
      "https://updates.push.services.mozilla.com/wpush/v2/x",
      "https://wns2-par02p.notify.windows.com/w/?token=x",
    ]) {
      expect(isAllowedEndpoint(url)).toBe(true);
    }
    const padded = (length: number) => `https://web.push.apple.com/${"a".repeat(length - "https://web.push.apple.com/".length)}`;
    for (const url of [
      "http://web.push.apple.com/x",
      "https://web.push.apple.com:8443/x",
      "https://user:pw@web.push.apple.com/x",
      "https://push.apple.com.evil.com/x",
      "https://evilpush.apple.com/x", // no dot before "push"
      "https://localhost/x",
      "https://127.0.0.1/x",
      padded(1025),
      42,
      undefined,
    ]) {
      expect(isAllowedEndpoint(url)).toBe(false);
    }
    expect(isAllowedEndpoint(padded(1024))).toBe(true); // the limit itself is fine
  });

  test("looks at the parsed host, so tricks in the rest of the URL do not help", () => {
    for (const url of [
      "https://web.push.apple.com@evil.com/x", // the host is evil.com
      "https://evil.com\\.push.apple.com/x", // a backslash ends the host
      "https://evil.com#.push.apple.com/x",
      "https://evil.com/.push.apple.com",
      "https://evil.com?.push.apple.com",
      "https://fcm.googleapis.com.evil.com/x",
      "https://x.fcm.googleapis.com/x", // fcm.googleapis.com must match exactly
      "https://googleapis.com/x",
      "https://push.apple.com/x", // the suffix needs a host in front of it
      "https://.push.apple.com/x",
      "https://a..push.apple.com/x",
      "https://web.push.apple.com./x",
      "https://a_b.push.apple.com/x",
      "https://a$b.push.apple.com/x",
      "https://wns2-par02p.notify.windows.com:444/x",
      "ftp://web.push.apple.com/x",
      "wss://web.push.apple.com/x",
      "//web.push.apple.com/x",
      "web.push.apple.com/x",
      "",
      "not a url",
    ]) {
      expect(isAllowedEndpoint(url)).toBe(false);
    }
  });

  test("takes the URL as the browser gives it: any case, the default port, no path", () => {
    expect(isAllowedEndpoint("https://WEB.PUSH.APPLE.COM/x")).toBe(true);
    expect(isAllowedEndpoint("https://web.push.apple.com:443/x")).toBe(true);
    expect(isAllowedEndpoint("https://web.push.apple.com")).toBe(true);
  });

  test("only strings count", () => {
    for (const value of [null, {}, [APPLE], new String(APPLE), new URL(APPLE), Buffer.from(APPLE), true]) {
      expect(isAllowedEndpoint(value)).toBe(false);
    }
  });
});

// --- validating what a phone hands over -----------------------------------------------------

describe("validSubscriptionKeys and validVapid", () => {
  test("checks subscription keys and VAPID keys", () => {
    const subscriber = makeSubscriber();
    expect(validSubscriptionKeys(subscriber.keys)).toBe(true);
    // a key with a - or _ in it, which the standard alphabet spells with + or /
    let unsafe = makeSubscriber();
    while (!/[-_]/.test(unsafe.keys.p256dh)) unsafe = makeSubscriber();
    expect(validSubscriptionKeys(unsafe.keys)).toBe(true);
    expect(standardBase64(unsafe.keys.p256dh)).not.toBe(unsafe.keys.p256dh);

    const wrongSubscription: unknown[] = [
      { ...subscriber.keys, p256dh: bytes(64) }, // wrong lengths
      { ...subscriber.keys, p256dh: bytes(66) },
      { ...subscriber.keys, auth: bytes(15) },
      { ...subscriber.keys, auth: bytes(17) },
      { ...subscriber.keys, p256dh: bytes(65, 3) }, // not an uncompressed point
      { ...subscriber.keys, p256dh: bytes(65, 0) },
      { ...subscriber.keys, p256dh: `${subscriber.keys.p256dh}=` }, // padded: base64url has none
      { ...subscriber.keys, p256dh: `${subscriber.keys.p256dh}!` }, // a character a lenient decoder skips
      { ...unsafe.keys, p256dh: standardBase64(unsafe.keys.p256dh) }, // the + and / alphabet
      { ...subscriber.keys, p256dh: "A".repeat(10_000) }, // far too long
      { ...subscriber.keys, p256dh: 42 }, // not strings
      { ...subscriber.keys, auth: null },
      { ...subscriber.keys, auth: [subscriber.keys.auth] },
      { ...subscriber.keys, auth: Buffer.from(subscriber.auth) },
      { p256dh: subscriber.keys.p256dh }, // missing
      { auth: subscriber.keys.auth },
      {},
      [],
      "keys",
      null,
      undefined,
    ];
    for (const wrong of wrongSubscription) expect(validSubscriptionKeys(wrong)).toBe(false);

    const vapid = makeVapid();
    expect(validVapid(vapid)).toBe(true);
    // WebCrypto's export carries more members; they do no harm
    expect(validVapid({ publicKey: vapid.publicKey, privateJwk: { ...vapid.privateJwk, ext: true, key_ops: ["sign"] } })).toBe(true);

    const other = makeVapid();
    const withJwk = (privateJwk: unknown) => ({ publicKey: vapid.publicKey, privateJwk });
    const wrongVapid: unknown[] = [
      { ...vapid, publicKey: bytes(64) }, // wrong lengths
      { ...vapid, publicKey: bytes(66) },
      { ...vapid, publicKey: bytes(65, 3) }, // not an uncompressed point
      { ...vapid, publicKey: 42 }, // not strings
      { ...vapid, publicKey: undefined },
      { privateJwk: vapid.privateJwk },
      { publicKey: vapid.publicKey },
      withJwk({ ...vapid.privateJwk, x: other.privateJwk.x }), // a JWK that is not the public key's
      withJwk({ ...vapid.privateJwk, y: other.privateJwk.y }),
      withJwk({ ...vapid.privateJwk, x: other.privateJwk.x, y: other.privateJwk.y }), // a whole other point: on the curve, so only the comparison catches it
      withJwk({ ...vapid.privateJwk, d: other.privateJwk.d }), // a private key of another pair
      withJwk({ ...vapid.privateJwk, kty: "RSA" }), // not an EC key on P-256
      withJwk({ ...vapid.privateJwk, crv: "P-384" }),
      withJwk({ kty: "RSA", n: "AQAB", e: "AQAB", d: "AQAB" }),
      withJwk({ ...vapid.privateJwk, d: undefined }), // a public key only
      withJwk({ ...vapid.privateJwk, d: bytes(31) }), // wrong lengths
      withJwk({ ...vapid.privateJwk, x: bytes(33, 1) }),
      withJwk({ ...vapid.privateJwk, y: b64url(crypto.randomBytes(31)) }),
      withJwk({ ...vapid.privateJwk, d: 7 }), // not strings
      withJwk({ ...vapid.privateJwk, x: null }),
      withJwk({ ...vapid.privateJwk, x: `${vapid.privateJwk.x}=` }), // padded
      withJwk("jwk"),
      withJwk(null),
      withJwk([]),
      { publicKey: vapid.publicKey, privateJwk: JSON.stringify(vapid.privateJwk) },
      {},
      [],
      "vapid",
      null,
      undefined,
    ];
    for (const wrong of wrongVapid) expect(validVapid(wrong)).toBe(false);
  });

  test("a JWK that validates can sign what its public key verifies", () => {
    const vapid = makeVapid();
    expect(validVapid(vapid)).toBe(true);
    const header = vapidAuthorization({ endpoint: APPLE, publicKey: vapid.publicKey, privateJwk: vapid.privateJwk, subject: SUBJECT });
    expect(verifies(parseVapid(header))).toBe(true);
  });
});

describe("b64url", () => {
  test("encodes bytes as base64url without padding", () => {
    expect(b64url(Buffer.from([0xfb, 0xff]))).toBe("-_8");
    expect(b64url(Buffer.from([1, 2, 3, 4]))).toBe("AQIDBA");
    expect(b64url(new Uint8Array([0xff, 0xfe]))).toBe("__4");
    expect(b64url(Buffer.alloc(0))).toBe("");
  });
});

// --- sendPush -------------------------------------------------------------------------------

describe("sendPush", () => {
  test("sendPush posts the encrypted body with the push headers", async () => {
    const { push, subscriber, vapid } = makePush();
    const { request, calls } = fakeRequest();

    const result = await sendPush(push, { request });

    expect(result).toEqual({ ok: true, status: 201, gone: false });
    expect(calls).toHaveLength(1);
    const [call] = calls;
    expect(call.url).toBe(APPLE);
    expect(call.method).toBe("POST");
    expect(call.ended).toBe(true);
    expect(call.headers).toMatchObject({
      TTL: "3600",
      Urgency: "high",
      Topic: "k3X-0_abcDEF123",
      "Content-Encoding": "aes128gcm",
      "Content-Type": "application/octet-stream",
      "Content-Length": String(call.body.length),
    });
    expect(call.headers.Authorization).toStartWith("vapid t=");
    expect(decrypt(call.body, subscriber).toString("utf8")).toBe(push.payload);
    // the authorization names this endpoint, this subject and this key, and its signature holds
    const parsed = parseVapid(call.headers.Authorization);
    expect(parsed.key).toBe(vapid.publicKey);
    expect(parsed.claims).toMatchObject({ aud: "https://web.push.apple.com", sub: SUBJECT });
    expect(verifies(parsed)).toBe(true);
    expect(call.drained).toBe(true);
  });

  test("leaves out Urgency and Topic when they are not given", async () => {
    const { push } = makePush({ urgency: undefined, topic: undefined });
    const { request, calls } = fakeRequest();
    expect((await sendPush(push, { request })).ok).toBe(true);
    expect(Object.keys(calls[0].headers).sort()).toEqual(["Authorization", "Content-Encoding", "Content-Length", "Content-Type", "TTL"]);
  });

  test("sends a payload given as a Buffer", async () => {
    const payload = crypto.randomBytes(200);
    const { push, subscriber } = makePush({ payload });
    const { request, calls } = fakeRequest();
    expect((await sendPush(push, { request })).ok).toBe(true);
    expect(decrypt(calls[0].body, subscriber).equals(payload)).toBe(true);
  });

  test("sendPush reports gone, refused and failed pushes without throwing", async () => {
    // a push service's answers
    for (const [status, expected] of [
      [200, { ok: true, status: 200, gone: false }],
      [201, { ok: true, status: 201, gone: false }],
      [202, { ok: true, status: 202, gone: false }],
      [410, { ok: false, status: 410, gone: true }],
      [404, { ok: false, status: 404, gone: true }],
      [429, { ok: false, status: 429, gone: false }],
      [400, { ok: false, status: 400, gone: false }],
      [403, { ok: false, status: 403, gone: false }],
      [413, { ok: false, status: 413, gone: false }],
      [500, { ok: false, status: 500, gone: false }],
      [503, { ok: false, status: 503, gone: false }],
      [301, { ok: false, status: 301, gone: false }], // a redirect is no success (https.request does not follow it)
    ] as const) {
      const { request, calls } = fakeRequest((_req, answer) => answer(status));
      expect(await sendPush(makePush().push, { request })).toEqual(expected);
      expect(calls[0].drained).toBe(true); // whatever it said, the body is read off
    }

    // a request that fails
    {
      const { request } = fakeRequest((req) => queueMicrotask(() => req.emit("error", new Error("socket hang up"))));
      expect(await sendPush(makePush().push, { request })).toEqual(FAILED);
    }

    // a request that never answers
    {
      const { request, calls } = fakeRequest(() => {});
      const started = Date.now();
      expect(await sendPush(makePush().push, { request, timeoutMs: 50 })).toEqual(FAILED);
      expect(Date.now() - started).toBeLessThan(1000);
      expect(calls[0].destroyed).toBe(true);
    }

    // an endpoint the allowlist refuses
    for (const endpoint of ["https://example.com/push", "http://web.push.apple.com/x", "https://127.0.0.1/x", "not a url", 42, undefined]) {
      const { request, calls } = fakeRequest();
      expect(await sendPush(makePush({ endpoint }).push, { request })).toEqual(FAILED);
      expect(calls).toHaveLength(0);
    }

    // a payload that does not fit
    {
      const { request, calls } = fakeRequest();
      expect(await sendPush(makePush({ payload: "x".repeat(5000) }).push, { request })).toEqual(FAILED);
      expect(calls).toHaveLength(0);
    }
  });

  test("a body of exactly 4096 bytes goes out and one byte more does not", async () => {
    // header 86 bytes + payload + delimiter + tag 16 = payload + 103
    const { request, calls } = fakeRequest();
    expect(await sendPush(makePush({ payload: "x".repeat(3993) }).push, { request })).toEqual({ ok: true, status: 201, gone: false });
    expect(calls[0].body).toHaveLength(4096);
    expect(await sendPush(makePush({ payload: "x".repeat(3994) }).push, { request })).toEqual(FAILED);
    expect(calls).toHaveLength(1);
  });

  test("the size limit counts bytes, not characters", async () => {
    const { request, calls } = fakeRequest();
    // 1000 emoji are 1000 characters (2000 UTF-16 units) and 4000 bytes
    expect(await sendPush(makePush({ payload: "🎉".repeat(1000) }).push, { request })).toEqual(FAILED);
    expect(calls).toHaveLength(0);
  });

  test("an injected allowEndpoint replaces the allowlist", async () => {
    const local = "http://127.0.0.1:8123/push/abc";
    const { push, subscriber } = makePush({ endpoint: local });
    const refused = fakeRequest();
    expect(await sendPush(push, { request: refused.request })).toEqual(FAILED); // the default allowlist says no
    expect(refused.calls).toHaveLength(0);

    const allowed = fakeRequest();
    expect(await sendPush(push, { request: allowed.request, allowEndpoint: () => true })).toEqual({ ok: true, status: 201, gone: false });
    expect(allowed.calls[0].url).toBe(local);
    expect(parseVapid(allowed.calls[0].headers.Authorization).claims.aud).toBe("http://127.0.0.1:8123");
    expect(decrypt(allowed.calls[0].body, subscriber).toString()).toBe(push.payload);

    const strict = fakeRequest();
    expect(await sendPush(makePush().push, { request: strict.request, allowEndpoint: () => false })).toEqual(FAILED);
    expect(strict.calls).toHaveLength(0);
    // the injected check is asked about the push's endpoint
    const asked: unknown[] = [];
    await sendPush(makePush().push, { request: strict.request, allowEndpoint: (url: unknown) => (asked.push(url), true) });
    expect(asked).toEqual([APPLE]);
  });

  test("never rejects, whatever it is given or whatever fails", async () => {
    const { request, calls } = fakeRequest();
    for (const push of [undefined, null, {}, 42, "push", [], { endpoint: APPLE }]) {
      expect(await sendPush(push as any, { request })).toEqual(FAILED);
    }
    for (const overrides of [
      { keys: undefined },
      { keys: { p256dh: bytes(64), auth: bytes(16) } },
      { keys: { p256dh: bytes(65), auth: bytes(16) } }, // not a point on the curve
      { vapid: undefined },
      { vapid: { publicKey: "x", privateJwk: { kty: "EC" } } },
      { subject: undefined, vapid: null },
      { payload: undefined },
      { payload: 42 },
      { ttl: undefined },
      { ttl: -1 },
      { ttl: 1.5 },
      { ttl: "3600" },
    ]) {
      expect(await sendPush(makePush(overrides).push, { request })).toEqual(FAILED);
    }
    expect(calls).toHaveLength(0);

    // collaborators that throw
    expect(await sendPush(makePush().push, { request, allowEndpoint: () => { throw new Error("boom"); } })).toEqual(FAILED);
    const throwing = (() => { throw new Error("invalid header value"); }) as any;
    expect(await sendPush(makePush().push, { request: throwing })).toEqual(FAILED);
    const failing = fakeRequest((req) => req.emit("error", new Error("refused")));
    expect(await sendPush(makePush().push, { request: failing.request })).toEqual(FAILED);
  });

  test("settles once, with the first outcome, and stops the timer when it has an answer", async () => {
    // an answer, then an error on the request: the answer stands
    const answerThenError = fakeRequest((req, answer) => {
      answer(201);
      req.emit("error", new Error("reset after the answer"));
    });
    expect(await sendPush(makePush().push, { request: answerThenError.request, timeoutMs: 50 })).toEqual({ ok: true, status: 201, gone: false });
    // the timeout does not destroy a request that has been answered
    await sleep(120);
    expect(answerThenError.calls[0].destroyed).toBe(false);

    // an error, then an answer: the error stands
    const errorThenAnswer = fakeRequest((req, answer) => {
      req.emit("error", new Error("reset"));
      answer(201);
    });
    expect(await sendPush(makePush().push, { request: errorThenAnswer.request })).toEqual(FAILED);

    // a late answer after the timeout cannot change the result either
    let lateAnswer: (status: number) => unknown = () => {};
    const slow = fakeRequest((_req, answer) => {
      lateAnswer = answer;
    });
    expect(await sendPush(makePush().push, { request: slow.request, timeoutMs: 30 })).toEqual(FAILED);
    lateAnswer(201);
    expect(slow.calls[0].destroyed).toBe(true);
  });

  test("a response whose body stalls after its headers is destroyed at the timeout", async () => {
    // The status is known, but the body never ends: the timer must still be armed and destroy it.
    const stalled = fakeRequest((_req, answer) => {
      const res = answer(201);
      res.removeAllListeners("end"); // the stub's end never comes for this response
      res.resume = () => {}; // and it is never drained either
    });
    const result = await sendPush(makePush().push, { request: stalled.request, timeoutMs: 40 });
    expect(result).toEqual({ ok: true, status: 201, gone: false });
    await sleep(80);
    expect(stalled.calls[0].destroyed).toBe(true);
  });

  test("a connection that drops while the response body is read does not escape as an error", async () => {
    // an EventEmitter throws for an 'error' nobody listens to; here that would be an uncaught exception
    const dropped = fakeRequest((_req, answer) => {
      const res = answer(201);
      setTimeout(() => res.emit("error", new Error("aborted")), 5);
    });
    expect(await sendPush(makePush().push, { request: dropped.request })).toEqual({ ok: true, status: 201, gone: false });
    await sleep(40);
  });

  test("two pushes at once do not mix their keys, headers or bodies", async () => {
    const first = makePush({ topic: "first" });
    const second = makePush({ topic: "second", endpoint: "https://fcm.googleapis.com/fcm/send/abc" });
    const { request, calls } = fakeRequest();
    const results = await Promise.all([sendPush(first.push, { request }), sendPush(second.push, { request })]);
    expect(results).toEqual([{ ok: true, status: 201, gone: false }, { ok: true, status: 201, gone: false }]);
    const byTopic = Object.fromEntries(calls.map((call) => [call.headers.Topic, call]));
    expect(decrypt(byTopic.first.body, first.subscriber).toString()).toBe(first.push.payload);
    expect(decrypt(byTopic.second.body, second.subscriber).toString()).toBe(second.push.payload);
    expect(byTopic.second.url).toBe("https://fcm.googleapis.com/fcm/send/abc");
  });
});

// ---- the production runtime ---------------------------------------------------------------------

describe("under real Node", () => {
  test.skipIf(!Bun.which("node"))(
    "the RFC 8291 vector and a loopback push (remote-bridge/test/webpush-smoke.js)",
    async () => {
      const proc = Bun.spawn(["node", path.join(import.meta.dir, "webpush-smoke.js")], { stdout: "pipe", stderr: "pipe" });
      const [code, out, err] = await Promise.all([proc.exited, new Response(proc.stdout).text(), new Response(proc.stderr).text()]);
      expect({ code, err }).toEqual({ code: 0, err: "" });
      expect(out).toContain("webpush smoke: ok");
    },
    30_000,
  );
});
